import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";

function MapView() {
  const [revendas, setRevendas] = useState([]);
  const [meta, setMeta] = useState({ progresso: 0, ultimaAtualizacao: null });
  const [loading, setLoading] = useState(true);

  // Buscar meta periodicamente
  useEffect(() => {
    const interval = setInterval(() => {
      fetch("http://192.168.0.81:5000/api/meta") // ⚠️ ajustar para o IP da tua rede
        .then((res) => res.json())
        .then((data) => {
          setMeta(data);
          if (data.progresso === 100) {
            fetch("http://192.168.0.81:5000/api/revendas")
              .then((res) => res.json())
              .then((dados) => {
                setRevendas(dados);
                setLoading(false);
              });
          }
        });
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div
        style={{
          height: "100vh",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          background: "#f9f9f9",
        }}
      >
        <h2>🔄 Carregando dados da ANP...</h2>
        <p>{meta.progresso}% concluído</p>
        <div
          style={{
            width: "60%",
            background: "#ddd",
            borderRadius: "10px",
            overflow: "hidden",
            marginTop: "10px",
          }}
        >
          <div
            style={{
              width: `${meta.progresso}%`,
              height: "15px",
              background: "#4caf50",
              transition: "width 0.5s",
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <MapContainer
      center={[-23.55, -46.63]}
      zoom={6}
      style={{ height: "100vh", width: "100%" }}
    >
      <TileLayer
        attribution="&copy; OpenStreetMap"
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />
      {revendas
        .filter((r) => r.latitude && r.longitude)
        .map((r, idx) => (
          <Marker key={idx} position={[r.latitude, r.longitude]}>
            <Popup>
              <b>{r.razao_social}</b> <br />
              {r.rua}, {r.bairro}, {r.municipio}/{r.uf} <br />
              CNPJ: {r.cnpj} <br />
              <a
                href={`https://waze.com/ul?ll=${r.latitude},${r.longitude}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                Abrir no Waze
              </a>{" "}
              |{" "}
              <a
                href={`https://www.google.com/maps?q=${r.latitude},${r.longitude}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                Abrir no Maps
              </a>
            </Popup>
          </Marker>
        ))}
    </MapContainer>
  );
}

export default MapView;
